import { Text, Billboard, Line as DreiLine } from "@react-three/drei";
import { useDoorConfig } from "@/lib/stores/useDoorConfig";
import * as THREE from "three";

interface DimensionLabelProps {
  position: [number, number, number];
  text: string;
  rotation?: [number, number, number];
}

export function DimensionLabel({ position, text, rotation = [0, 0, 0] }: DimensionLabelProps) {
  return (
    <Billboard position={position} follow={true} lockX={false} lockY={false} lockZ={false}>
      <Text
        fontSize={0.1}
        color="#1a1a1a"
        anchorX="center"
        anchorY="middle"
        outlineWidth={0.005}
        outlineColor="#ffffff"
      >
        {text}
      </Text>
    </Billboard>
  );
}

export function DoorDimensions() {
  const { width, mainHeight, thickness, showDimensions, borderHeight, borderStyle, shape, topWidth } = useDoorConfig();

  if (!showDimensions) return null;

  const w = width / 1000;
  const h = mainHeight / 1000;
  const t = thickness / 1000;
  const showBorders = borderStyle !== "none";
  const isAngled = shape === "angled";

  return (
    <group>
      {/* Width label - bottom */}
      <DimensionLabel
        position={[0, -h / 2 - 0.15, 0]}
        text={`${width}mm`}
      />

      {/* Height label - right side */}
      <DimensionLabel
        position={[w / 2 + 0.2, 0, 0]}
        text={`${mainHeight}mm`}
        rotation={[0, 0, Math.PI / 2]}
      />

      {/* Thickness label - top right */}
      <DimensionLabel
        position={[w / 2 + 0.15, h / 2 + 0.1, t / 2]}
        text={`${thickness}mm`}
      />

      {/* Top Width label for angled doors */}
      {isAngled && (
        <DimensionLabel
          position={[0, h / 2 + 0.15, 0]}
          text={`${topWidth}mm`}
        />
      )}

      {/* Top Border label */}
      {showBorders && borderHeight.top > 0 && (
        <DimensionLabel
          position={[-w / 2 - 0.15, h / 2 - (borderHeight.top / 2000), t / 2 + 0.05]}
          text={`${borderHeight.top}mm`}
        />
      )}

      {/* Bottom Border label */}
      {showBorders && borderHeight.bottom > 0 && (
        <DimensionLabel
          position={[-w / 2 - 0.15, -h / 2 + (borderHeight.bottom / 2000), t / 2 + 0.05]}
          text={`${borderHeight.bottom}mm`}
        />
      )}

      {/* Dimension lines */}
      <Line
        points={[
          [-w / 2, -h / 2 - 0.1, 0],
          [w / 2, -h / 2 - 0.1, 0],
        ]}
      />
      <Line
        points={[
          [w / 2 + 0.1, -h / 2, 0],
          [w / 2 + 0.1, h / 2, 0],
        ]}
      />

      {/* Border dimension lines */}
      {showBorders && borderHeight.top > 0 && (
        <Line
          points={[
            [-w / 2 - 0.08, h / 2, t / 2 + 0.02],
            [-w / 2 - 0.08, h / 2 - (borderHeight.top / 1000), t / 2 + 0.02],
          ]}
        />
      )}
      {showBorders && borderHeight.bottom > 0 && (
        <Line
          points={[
            [-w / 2 - 0.08, -h / 2, t / 2 + 0.02],
            [-w / 2 - 0.08, -h / 2 + (borderHeight.bottom / 1000), t / 2 + 0.02],
          ]}
        />
      )}
    </group>
  );
}

// Simple line component using Drei Line for better rendering
function Line({ points }: { points: [number, number, number][] }) {
  return (
    <DreiLine
      points={points}
      color="#999999"
      lineWidth={1.5}
      dashed={false}
    />
  );
}

