import { create } from "zustand";

export type DoorPreset = "single" | "double" | "shaker_2" | "shaker_4" | "shaker_6" | "panel_3" | "panel_4" | "panel_6";
export type PanelType = "flat" | "shaker" | "raised";
export type BorderStyle = "none" | "simple" | "detailed";
export type DoorShape = "rectangular" | "angled";
export type MaterialType = "oak" | "pine" | "walnut" | "mahogany" | "maple" | "cherry";
export type FinishType = "natural" | "stained" | "painted" | "varnished";
export type ColorShade = "light" | "medium" | "dark" | "white" | "black" | "grey" | "natural_wood";

export interface MidRail {
  id: string;
  positionFromBottom: number;
  dimension: number;
}

export interface DoorConfig {
  width: number;
  height: number;
  thickness: number;
  mainHeight: number;
  secondaryHeight: number;
  topWidth: number;
  preset: DoorPreset;
  panelType: PanelType;
  panelCount: number;
  shape: DoorShape;

  angledLeft: boolean;
  angledRight: boolean;
  leftTriangleCutoutWidth: number;
  leftTriangleCutoutHeight: number;
  rightTriangleCutoutWidth: number;
  rightTriangleCutoutHeight: number;

  borderWidth: number;
  customBorders: boolean;
  leftStile: number;
  rightStile: number;
  bottomRail: number;
  topRail: number;

  midRailsEnabled: boolean;
  midRailsEqualise: boolean;
  midRails: MidRail[];

  hingeDrilling: boolean;

  railPosition: {
    top: number;
    middle: number;
  };
  railHeights: {
    top: number;
    middle: number;
  };
  borderHeight: {
    top: number;
    bottom: number;
  };
  borderStyle: BorderStyle;
  borderMode: "equal" | "custom";
  lastCustomHeights: {
    top: number;
    bottom: number;
  };

  material: MaterialType;
  finish: FinishType;
  color: ColorShade;
  showDimensions: boolean;
  basePrice: number;
  price: number;
}

interface DoorConfigStore extends DoorConfig {
  setWidth: (width: number) => void;
  setHeight: (height: number) => void;
  setThickness: (thickness: number) => void;
  setMainHeight: (height: number) => void;
  setSecondaryHeight: (height: number) => void;
  setTopWidth: (width: number) => void;
  setPreset: (preset: DoorPreset) => void;
  setPanelType: (type: PanelType) => void;
  setPanelCount: (count: number) => void;
  setShape: (shape: DoorShape) => void;

  setAngledLeft: (enabled: boolean) => void;
  setAngledRight: (enabled: boolean) => void;
  setLeftTriangleCutoutWidth: (width: number) => void;
  setLeftTriangleCutoutHeight: (height: number) => void;
  setRightTriangleCutoutWidth: (width: number) => void;
  setRightTriangleCutoutHeight: (height: number) => void;

  setBorderWidth: (width: number) => void;
  setCustomBorders: (enabled: boolean) => void;
  setLeftStile: (width: number) => void;
  setRightStile: (width: number) => void;
  setBottomRail: (height: number) => void;
  setTopRail: (height: number) => void;

  setMidRailsEnabled: (enabled: boolean) => void;
  setMidRailsEqualise: (enabled: boolean) => void;
  addMidRail: () => void;
  removeMidRail: (id: string) => void;
  updateMidRail: (id: string, field: 'positionFromBottom' | 'dimension', value: number) => void;

  setHingeDrilling: (enabled: boolean) => void;

  setRailPosition: (position: 'top' | 'middle', value: number) => void;
  setRailHeight: (position: 'top' | 'middle', value: number) => void;
  setBorderHeight: (position: 'top' | 'bottom', value: number) => void;
  setBorderStyle: (style: BorderStyle) => void;
  setBorderMode: (mode: "equal" | "custom") => void;
  setMaterial: (material: MaterialType) => void;
  setFinish: (finish: FinishType) => void;
  setColor: (color: ColorShade) => void;
  toggleDimensions: () => void;
  calculatePrice: () => void;
  resetConfig: () => void;
}

const BASE_PRICE = 107.00;

const PRESET_CONFIGS: Record<DoorPreset, Partial<DoorConfig>> = {
  single: {
    panelCount: 1,
    panelType: "flat",
    width: 600,
    height: 1881,
  },
  double: {
    panelCount: 2,
    panelType: "shaker",
    width: 600,
    height: 2000,
    mainHeight: 2000,
    secondaryHeight: 1294,
  },
  shaker_2: {
    panelCount: 2,
    panelType: "shaker",
    width: 600,
    height: 2000,
  },
  shaker_4: {
    panelCount: 4,
    panelType: "shaker",
    width: 600,
    height: 2000,
  },
  shaker_6: {
    panelCount: 6,
    panelType: "shaker",
    width: 600,
    height: 2000,
  },
  panel_3: {
    panelCount: 3,
    panelType: "raised",
    width: 600,
    height: 2000,
  },
  panel_4: {
    panelCount: 4,
    panelType: "raised",
    width: 600,
    height: 2000,
  },
  panel_6: {
    panelCount: 6,
    panelType: "raised",
    width: 600,
    height: 2000,
  },
};

const initialState: DoorConfig = {
  width: 400,
  height: 1200,
  thickness: 22,
  mainHeight: 1200,
  secondaryHeight: 1294,
  topWidth: 300,
  preset: "single",
  panelType: "flat",
  panelCount: 1,
  shape: "rectangular",

  angledLeft: false,
  angledRight: false,
  leftTriangleCutoutWidth: 200,
  leftTriangleCutoutHeight: 300,
  rightTriangleCutoutWidth: 200,
  rightTriangleCutoutHeight: 300,

  borderWidth: 75,
  customBorders: false,
  leftStile: 75,
  rightStile: 75,
  bottomRail: 75,
  topRail: 75,

  midRailsEnabled: false,
  midRailsEqualise: false,
  midRails: [],

  hingeDrilling: false,

  railPosition: {
    top: 100,
    middle: 50,
  },
  railHeights: {
    top: 150,
    middle: 150,
  },
  borderHeight: {
    top: 50,
    bottom: 50,
  },
  borderStyle: "none",
  borderMode: "equal",
  lastCustomHeights: {
    top: 50,
    bottom: 50,
  },
  material: "oak",
  finish: "natural",
  color: "natural_wood",
  showDimensions: true,
  basePrice: BASE_PRICE,
  price: BASE_PRICE,
};

let midRailIdCounter = 0;

export const useDoorConfig = create<DoorConfigStore>((set, get) => ({
  ...initialState,

  setWidth: (width) => {
    set({ width });
    get().calculatePrice();
  },

  setHeight: (height) => {
    set({ height, mainHeight: height });
    get().calculatePrice();
  },

  setThickness: (thickness) => {
    set({ thickness });
    get().calculatePrice();
  },

  setMainHeight: (mainHeight) => {
    set({ mainHeight, height: mainHeight });
    get().calculatePrice();
  },

  setSecondaryHeight: (secondaryHeight) => {
    set({ secondaryHeight });
    get().calculatePrice();
  },

  setTopWidth: (topWidth) => {
    set({ topWidth });
  },

  setPreset: (preset) => {
    const config = PRESET_CONFIGS[preset];
    const state = get();
    const newTop = config.borderHeight?.top ?? state.borderHeight.top;
    const newBottom = config.borderHeight?.bottom ?? state.borderHeight.bottom;
    const borderMode = newTop === newBottom ? "equal" : "custom";

    set({ 
      preset, 
      ...config,
      borderMode,
      lastCustomHeights: {
        top: newTop,
        bottom: newBottom,
      },
    });
    get().calculatePrice();
  },

  setPanelType: (panelType) => {
    set({ panelType });
    get().calculatePrice();
  },

  setPanelCount: (panelCount) => {
    set({ panelCount });
    get().calculatePrice();
  },

  setShape: (shape) => {
    set({ shape });
  },

  setAngledLeft: (angledLeft) => {
    set({ angledLeft });
  },

  setAngledRight: (angledRight) => {
    set({ angledRight });
  },

  setLeftTriangleCutoutWidth: (leftTriangleCutoutWidth) => {
    set({ leftTriangleCutoutWidth });
  },

  setLeftTriangleCutoutHeight: (leftTriangleCutoutHeight) => {
    set({ leftTriangleCutoutHeight });
  },

  setRightTriangleCutoutWidth: (rightTriangleCutoutWidth) => {
    set({ rightTriangleCutoutWidth });
  },

  setRightTriangleCutoutHeight: (rightTriangleCutoutHeight) => {
    set({ rightTriangleCutoutHeight });
  },

  setBorderWidth: (borderWidth) => {
    set({ 
      borderWidth,
      leftStile: borderWidth,
      rightStile: borderWidth,
      bottomRail: borderWidth,
      topRail: borderWidth,
    });
  },

  setCustomBorders: (customBorders) => {
    const state = get();
    if (!customBorders) {
      set({ 
        customBorders,
        leftStile: state.borderWidth,
        rightStile: state.borderWidth,
        bottomRail: state.borderWidth,
        topRail: state.borderWidth,
      });
    } else {
      set({ customBorders });
    }
  },

  setLeftStile: (leftStile) => {
    set({ leftStile });
  },

  setRightStile: (rightStile) => {
    set({ rightStile });
  },

  setBottomRail: (bottomRail) => {
    set({ bottomRail });
  },

  setTopRail: (topRail) => {
    set({ topRail });
  },

  setMidRailsEnabled: (midRailsEnabled) => {
    set({ midRailsEnabled });
    if (midRailsEnabled && get().midRails.length === 0) {
      get().addMidRail();
    }
  },

  setMidRailsEqualise: (midRailsEqualise) => {
    const state = get();
    if (midRailsEqualise && state.midRails.length > 0) {
      const railCount = state.midRails.length;
      const usableHeight = state.height - state.bottomRail - state.topRail;
      const spacing = usableHeight / (railCount + 1);

      const updatedRails = state.midRails.map((rail, index) => ({
        ...rail,
        positionFromBottom: Math.round(state.bottomRail + spacing * (index + 1)),
      }));

      set({ midRailsEqualise, midRails: updatedRails });
    } else {
      set({ midRailsEqualise });
    }
  },

  addMidRail: () => {
    const state = get();
    const newRail: MidRail = {
      id: `rail_${++midRailIdCounter}`,
      positionFromBottom: Math.round(state.height / 2),
      dimension: 75,
    };
    set({ midRails: [...state.midRails, newRail] });
  },

  removeMidRail: (id) => {
    set((state) => ({
      midRails: state.midRails.filter(rail => rail.id !== id)
    }));
  },

  updateMidRail: (id, field, value) => {
    set((state) => ({
      midRails: state.midRails.map(rail =>
        rail.id === id ? { ...rail, [field]: value } : rail
      )
    }));
  },

  setHingeDrilling: (hingeDrilling) => {
    set({ hingeDrilling });
  },

  setRailPosition: (position, value) => {
    set((state) => ({
      railPosition: {
        ...state.railPosition,
        [position]: value,
      },
    }));
  },

  setRailHeight: (position, value) => {
    set((state) => ({
      railHeights: {
        ...state.railHeights,
        [position]: value,
      },
    }));
  },

  setBorderHeight: (position, value) => {
    const state = get();
    const roundedValue = Math.round(value / 5) * 5;

    if (state.borderMode === "equal") {
      set({
        borderHeight: {
          top: roundedValue,
          bottom: roundedValue,
        },
      });
    } else {
      set((state) => ({
        borderHeight: {
          ...state.borderHeight,
          [position]: roundedValue,
        },
        lastCustomHeights: {
          ...state.lastCustomHeights,
          [position]: roundedValue,
        },
      }));
    }
    get().calculatePrice();
  },

  setBorderStyle: (borderStyle) => {
    set({ borderStyle });
    get().calculatePrice();
  },

  setBorderMode: (borderMode) => {
    const state = get();

    if (borderMode === "equal") {
      const avgHeight = (state.borderHeight.top + state.borderHeight.bottom) / 2;
      const roundedHeight = Math.round(avgHeight / 5) * 5;
      set({
        borderMode,
        lastCustomHeights: {
          top: state.borderHeight.top,
          bottom: state.borderHeight.bottom,
        },
        borderHeight: {
          top: roundedHeight,
          bottom: roundedHeight,
        },
      });
    } else {
      set({
        borderMode,
        borderHeight: state.lastCustomHeights,
      });
    }
  },

  setMaterial: (material) => {
    set({ material });
    get().calculatePrice();
  },

  setFinish: (finish) => {
    set({ finish });
    get().calculatePrice();
  },

  setColor: (color) => {
    set({ color });
    get().calculatePrice();
  },

  toggleDimensions: () => {
    set((state) => ({ showDimensions: !state.showDimensions }));
  },

  calculatePrice: () => {
    const state = get();
    const areaM2 = (state.width * state.height) / 1000000;
    const pricePerM2 = 200;
    let price = BASE_PRICE + (areaM2 * pricePerM2);

    const panelMultiplier = {
      flat: 1.0,
      shaker: 1.2,
      raised: 1.4,
    };
    price *= panelMultiplier[state.panelType];
    price += (state.panelCount - 1) * 10;

    const borderCost = {
      none: 0,
      simple: 15,
      detailed: 30,
    };
    price += borderCost[state.borderStyle];

    if (state.thickness > 22) {
      price += (state.thickness - 22) * 0.5;
    }

    const materialCost = {
      oak: 0,
      pine: -20,
      walnut: 40,
      mahogany: 50,
      maple: 25,
      cherry: 35,
    };
    price += materialCost[state.material];

    const finishCost = {
      natural: 0,
      stained: 25,
      painted: 30,
      varnished: 20,
    };
    price += finishCost[state.finish];

    if (state.midRailsEnabled) {
      price += state.midRails.length * 15;
    }

    set({ price: Math.round(price * 100) / 100 });
  },

  resetConfig: () => {
    set(initialState);
    get().calculatePrice();
  },
}));

setTimeout(() => {
  useDoorConfig.getState().calculatePrice();
}, 0);

