import type { Express } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { doorConfigSchema, cartItemSchema } from "@shared/doorSchema";
import { generateDoorDxf, type DxfDoorConfig } from "./dxfGenerator";
import { generateDoorSvg, type SvgDoorConfig } from "./svgGenerator";
import { z } from "zod";

export async function registerRoutes(app: Express): Promise<Server> {
  // Door configuration endpoints
  app.post("/api/door-config", async (req, res) => {
    try {
      const config = doorConfigSchema.parse(req.body);
      const saved = await storage.saveDoorConfig(config);
      res.json(saved);
    } catch (error: any) {
      res.status(400).json({ message: error.message });
    }
  });

  app.get("/api/door-config/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const config = await storage.getDoorConfig(id);
      if (!config) {
        return res.status(404).json({ message: "Configuration not found" });
      }
      res.json(config);
    } catch (error: any) {
      res.status(400).json({ message: error.message });
    }
  });

  // Cart endpoints
  app.post("/api/cart", async (req, res) => {
    try {
      const itemData = {
        timestamp: new Date().toISOString(),
        config: doorConfigSchema.parse(req.body.config),
        quantity: req.body.quantity || 1,
      };
      const cartItem = await storage.addToCart(itemData);
      res.json(cartItem);
    } catch (error: any) {
      res.status(400).json({ message: error.message });
    }
  });

  app.get("/api/cart", async (req, res) => {
    try {
      const items = await storage.getCartItems();
      res.json(items);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.delete("/api/cart/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const removed = await storage.removeFromCart(id);
      if (!removed) {
        return res.status(404).json({ message: "Item not found" });
      }
      res.json({ message: "Item removed from cart" });
    } catch (error: any) {
      res.status(400).json({ message: error.message });
    }
  });

  app.delete("/api/cart", async (req, res) => {
    try {
      await storage.clearCart();
      res.json({ message: "Cart cleared" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // DXF Export endpoint
  const dxfExportSchema = z.object({
    width: z.number(),
    height: z.number().optional(),
    thickness: z.number(),
    mainHeight: z.number(),
    topWidth: z.number(),
    preset: z.string(),
    panelType: z.string(),
    panelCount: z.number(),
    shape: z.string(),
    railPosition: z.object({
      top: z.number(),
      middle: z.number(),
    }),
    railHeights: z.object({
      top: z.number(),
      middle: z.number(),
    }),
    borderHeight: z.object({
      top: z.number(),
      bottom: z.number(),
    }),
    borderStyle: z.string(),
    material: z.string(),
    finish: z.string(),
    color: z.string(),
  });

  app.post("/api/export/dxf", async (req, res) => {
    try {
      const parsed = dxfExportSchema.parse(req.body);
      const config: DxfDoorConfig = {
        ...parsed,
        height: parsed.height ?? parsed.mainHeight,
      };
      const dxfContent = generateDoorDxf(config);

      const filename = `door-${config.preset}-${config.width}x${config.mainHeight}-${Date.now()}.dxf`;

      res.setHeader("Content-Type", "application/dxf");
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
      res.send(dxfContent);
    } catch (error: any) {
      console.error("DXF Export Error:", error);
      res.status(422).json({ 
        message: "Failed to generate DXF file",
        details: error.message 
      });
    }
  });

  // SVG Export endpoint
  const svgExportSchema = z.object({
    width: z.number(),
    height: z.number().optional(),
    thickness: z.number(),
    mainHeight: z.number(),
    topWidth: z.number(),
    preset: z.string(),
    panelType: z.string(),
    panelCount: z.number(),
    shape: z.string(),
    angledLeft: z.boolean().optional(),
    angledRight: z.boolean().optional(),
    leftTriangleCutoutWidth: z.number().optional(),
    leftTriangleCutoutHeight: z.number().optional(),
    rightTriangleCutoutWidth: z.number().optional(),
    rightTriangleCutoutHeight: z.number().optional(),
    borderWidth: z.number().optional(),
    customBorders: z.boolean().optional(),
    leftStile: z.number().optional(),
    rightStile: z.number().optional(),
    bottomRail: z.number().optional(),
    topRail: z.number().optional(),
    midRailsEnabled: z.boolean().optional(),
    midRails: z.array(z.object({
      positionFromBottom: z.number(),
      dimension: z.number(),
    })).optional(),
    borderHeight: z.object({
      top: z.number(),
      bottom: z.number(),
    }),
    borderStyle: z.string(),
    material: z.string(),
    finish: z.string(),
    color: z.string(),
  });

  app.post("/api/export/svg", async (req, res) => {
    try {
      const parsed = svgExportSchema.parse(req.body);
      const config: SvgDoorConfig = {
        ...parsed,
        height: parsed.height ?? parsed.mainHeight,
        borderWidth: parsed.borderWidth ?? 75,
      };
      const svgContent = generateDoorSvg(config);

      const filename = `door-${config.preset}-${config.width}x${config.mainHeight}-${Date.now()}.svg`;

      res.setHeader("Content-Type", "image/svg+xml");
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
      res.send(svgContent);
    } catch (error: any) {
      console.error("SVG Export Error:", error);
      res.status(422).json({ 
        message: "Failed to generate SVG file",
        details: error.message 
      });
    }
  });

  const httpServer = createServer(app);

  return httpServer;
}

client/src/components/door/Door3D.tsx.content:
import { useRef, useMemo } from "react";
import { useFrame } from "@react-three/fiber";
import { useDoorConfig } from "@/lib/stores/useDoorConfig";
import * as THREE from "three";
import { useTexture } from "@react-three/drei";

function SingleDoorLeaf({ 
  width, 
  height, 
  thickness, 
  panelType, 
  panelCount, 
  borderHeight, 
  borderStyle,
  position = [0, 0, 0],
  woodTexture,
  doorColor,
  mirrorHandle = false,
  railPosition,
  angledLeft = false,
  angledRight = false,
  leftCutoutWidth = 0,
  leftCutoutHeight = 0,
  rightCutoutWidth = 0,
  rightCutoutHeight = 0,
  borderWidths,
  midRails = []
}: any) {
  const w = width / 1000;
  const h = height / 1000;
  const t = thickness / 1000;

  const leftCutW = leftCutoutWidth / 1000;
  const leftCutH = leftCutoutHeight / 1000;
  const rightCutW = rightCutoutWidth / 1000;
  const rightCutH = rightCutoutHeight / 1000;

  const doorGeometry = useMemo(() => {
    if (angledLeft || angledRight) {
      const shape = new THREE.Shape();

      shape.moveTo(-w/2, -h/2);
      shape.lineTo(w/2, -h/2);

      if (angledRight) {
        shape.lineTo(w/2, h/2 - rightCutH);
        shape.lineTo(w/2 - rightCutW, h/2);
      } else {
        shape.lineTo(w/2, h/2);
      }

      if (angledLeft) {
        shape.lineTo(-w/2 + leftCutW, h/2);
        shape.lineTo(-w/2, h/2 - leftCutH);
      } else {
        shape.lineTo(-w/2, h/2);
      }

      shape.lineTo(-w/2, -h/2);

      const extrudeSettings = {
        steps: 1,
        depth: t,
        bevelEnabled: false,
      };

      const geometry = new THREE.ExtrudeGeometry(shape, extrudeSettings);
      geometry.translate(0, 0, -t/2);
      geometry.computeVertexNormals();

      return geometry;
    }
    return null;
  }, [w, h, t, angledLeft, angledRight, leftCutW, leftCutH, rightCutW, rightCutH]);

  const doorPanels = useMemo(() => {
    const panels: JSX.Element[] = [];
    const leftStile = borderWidths?.leftStile ? borderWidths.leftStile / 1000 : 0.075;
    const rightStile = borderWidths?.rightStile ? borderWidths.rightStile / 1000 : 0.075;
    const topRailWidth = borderWidths?.topRail ? borderWidths.topRail / 1000 : 0.075;
    const bottomRailWidth = borderWidths?.bottomRail ? borderWidths.bottomRail / 1000 : 0.075;

    if (doorGeometry) {
      panels.push(
        <mesh key={`frame-angled-${leftCutW}-${rightCutW}`} castShadow receiveShadow geometry={doorGeometry}>
          <meshStandardMaterial map={woodTexture} color={doorColor} />
        </mesh>
      );
    } else {
      panels.push(
        <mesh key={`frame-rect-${w}-${h}-${t}`} castShadow receiveShadow>
          <boxGeometry args={[w, h, t]} />
          <meshStandardMaterial map={woodTexture} color={doorColor} />
        </mesh>
      );
    }

    const innerWidth = w - leftStile - rightStile;
    const innerHeight = h - topRailWidth - bottomRailWidth;
    const innerCenterX = (leftStile - rightStile) / 2;
    const innerCenterY = (bottomRailWidth - topRailWidth) / 2;

    if (panelType === "shaker" || panelType === "raised") {
      const frameThickness = 0.02;
      const panelHeight = (innerHeight - frameThickness * (panelCount + 1)) / panelCount;
      const panelWidth = innerWidth - frameThickness * 2;

      for (let i = 0; i < panelCount; i++) {
        const yPos = -h / 2 + bottomRailWidth + frameThickness + panelHeight / 2 + i * (panelHeight + frameThickness);

        if (panelType === "shaker") {
          panels.push(
            <mesh
              key={`panel-${i}`}
              position={[innerCenterX, yPos, t / 2 + 0.005]}
              castShadow
            >
              <boxGeometry args={[panelWidth - 0.04, panelHeight - 0.04, 0.01]} />
              <meshStandardMaterial color="#C89860" />
            </mesh>
          );

          panels.push(
            <mesh
              key={`panel-frame-${i}`}
              position={[innerCenterX, yPos, t / 2 + 0.01]}
            >
              <boxGeometry args={[panelWidth - 0.02, panelHeight - 0.02, 0.005]} />
              <meshStandardMaterial color="#B88850" />
            </mesh>
          );
        }

        if (panelType === "raised") {
          panels.push(
            <mesh
              key={`raised-panel-${i}`}
              position={[innerCenterX, yPos, t / 2 + 0.015]}
              castShadow
            >
              <boxGeometry args={[panelWidth - 0.06, panelHeight - 0.06, 0.03]} />
              <meshStandardMaterial map={woodTexture} color="#D4A574" />
            </mesh>
          );
        }
      }
    }

    if (midRails && midRails.length > 0) {
      midRails.forEach((rail: any, index: number) => {
        const railY = -h / 2 + rail.positionFromBottom / 1000;
        const railDim = rail.dimension / 1000;

        panels.push(
          <mesh
            key={`mid-rail-${index}`}
            position={[innerCenterX, railY, t / 2 + 0.008]}
            castShadow
          >
            <boxGeometry args={[innerWidth, railDim, 0.015]} />
            <meshStandardMaterial color="#8B6F47" />
          </mesh>
        );
      });
    }

    if (borderStyle !== "none") {
      const borderDepth = borderStyle === "detailed" ? 0.03 : 0.02;
      const topBorder = borderHeight.top / 1000;
      const bottomBorder = borderHeight.bottom / 1000;

      if (topBorder > 0) {
        panels.push(
          <mesh
            key="border-top"
            position={[0, h / 2 - topBorder / 2, t / 2 + borderDepth / 2]}
            castShadow
          >
            <boxGeometry args={[w - 0.02, topBorder, borderDepth]} />
            <meshStandardMaterial color="#A67C52" />
          </mesh>
        );
      }

      if (bottomBorder > 0) {
        panels.push(
          <mesh
            key="border-bottom"
            position={[0, -h / 2 + bottomBorder / 2, t / 2 + borderDepth / 2]}
            castShadow
          >
            <boxGeometry args={[w - 0.02, bottomBorder, borderDepth]} />
            <meshStandardMaterial color="#A67C52" />
          </mesh>
        );
      }
    }

    return panels;
  }, [w, h, t, panelType, panelCount, borderHeight, borderStyle, woodTexture, doorColor, borderWidths, midRails, doorGeometry, leftCutW, rightCutW]);

  const handleXPos = mirrorHandle ? -w * 0.35 : w * 0.35;

  return (
    <group position={position as [number, number, number]}>
      {doorPanels}

      <mesh position={[handleXPos, 0, t / 2 + 0.02]} castShadow>
        <cylinderGeometry args={[0.012, 0.012, 0.08, 16]} />
        <meshStandardMaterial color="#888888" metalness={0.8} roughness={0.2} />
      </mesh>
      <mesh position={[handleXPos, 0, t / 2 + 0.05]} castShadow>
        <sphereGeometry args={[0.02, 16, 16]} />
        <meshStandardMaterial color="#888888" metalness={0.8} roughness={0.2} />
      </mesh>
    </group>
  );
}

function getDoorColors(material: string, finish: string, color: string) {
  const colorMap: Record<string, string> = {
    natural_wood: "#D4A574",
    light: "#F5DEB3",
    medium: "#D2691E",
    dark: "#8B4513",
    white: "#FFFFFF",
    black: "#1a1a1a",
    grey: "#808080",
  };

  const materialTints: Record<string, string> = {
    oak: "#D4A574",
    pine: "#E3C79E",
    walnut: "#5C4033",
    mahogany: "#C04000",
    maple: "#E9C2A6",
    cherry: "#C95A49",
  };

  let baseColor = colorMap[color] || "#D4A574";

  if (finish === "painted") {
    return baseColor;
  } else if (finish === "stained" || finish === "varnished") {
    return color === "natural_wood" ? materialTints[material] : baseColor;
  } else {
    return materialTints[material];
  }
}

export function Door3D() {
  const meshRef = useRef<THREE.Group>(null);
  const config = useDoorConfig();
  const {
    width,
    height,
    thickness,
    mainHeight,
    panelType,
    panelCount,
    borderHeight,
    borderStyle,
    preset,
    material,
    finish,
    color,
    railPosition,
    angledLeft,
    angledRight,
    leftTriangleCutoutWidth,
    leftTriangleCutoutHeight,
    rightTriangleCutoutWidth,
    rightTriangleCutoutHeight,
    leftStile,
    rightStile,
    bottomRail,
    topRail,
    midRailsEnabled,
    midRails,
  } = config;

  const woodTexture = useTexture("/textures/wood.jpg");

  useMemo(() => {
    woodTexture.wrapS = woodTexture.wrapT = THREE.RepeatWrapping;
    woodTexture.repeat.set(2, 4);
  }, [woodTexture]);

  const doorColor = getDoorColors(material, finish, color);
  const isDoubleDoor = preset === "double";

  useFrame((state) => {
    if (meshRef.current) {
      meshRef.current.rotation.y = Math.sin(state.clock.elapsedTime * 0.2) * 0.05;
    }
  });

  const actualHeight = mainHeight || height;

  const borderWidths = {
    leftStile,
    rightStile,
    bottomRail,
    topRail,
  };

  const activeMidRails = midRailsEnabled ? midRails : [];

  return (
    <group ref={meshRef} position={[0, 0, 0]}>
      {isDoubleDoor ? (
        <>
          <SingleDoorLeaf
            width={width / 2}
            height={actualHeight}
            thickness={thickness}
            panelType={panelType}
            panelCount={panelCount}
            borderHeight={borderHeight}
            borderStyle={borderStyle}
            position={[-(width / 4000) - 0.005, 0, 0]}
            woodTexture={woodTexture}
            doorColor={doorColor}
            mirrorHandle={false}
            railPosition={railPosition}
            angledLeft={angledLeft}
            angledRight={false}
            leftCutoutWidth={leftTriangleCutoutWidth}
            leftCutoutHeight={leftTriangleCutoutHeight}
            rightCutoutWidth={0}
            rightCutoutHeight={0}
            borderWidths={borderWidths}
            midRails={activeMidRails}
          />
          <SingleDoorLeaf
            width={width / 2}
            height={actualHeight}
            thickness={thickness}
            panelType={panelType}
            panelCount={panelCount}
            borderHeight={borderHeight}
            borderStyle={borderStyle}
            position={[(width / 4000) + 0.005, 0, 0]}
            woodTexture={woodTexture}
            doorColor={doorColor}
            mirrorHandle={true}
            railPosition={railPosition}
            angledLeft={false}
            angledRight={angledRight}
            leftCutoutWidth={0}
            leftCutoutHeight={0}
            rightCutoutWidth={rightTriangleCutoutWidth}
            rightCutoutHeight={rightTriangleCutoutHeight}
            borderWidths={borderWidths}
            midRails={activeMidRails}
          />
        </>
      ) : (
        <SingleDoorLeaf
          width={width}
          height={actualHeight}
          thickness={thickness}
          panelType={panelType}
          panelCount={panelCount}
          borderHeight={borderHeight}
          borderStyle={borderStyle}
          position={[0, 0, 0]}
          woodTexture={woodTexture}
          doorColor={doorColor}
          mirrorHandle={false}
          railPosition={railPosition}
          angledLeft={angledLeft}
          angledRight={angledRight}
          leftCutoutWidth={leftTriangleCutoutWidth}
          leftCutoutHeight={leftTriangleCutoutHeight}
          rightCutoutWidth={rightTriangleCutoutWidth}
          rightCutoutHeight={rightTriangleCutoutHeight}
          borderWidths={borderWidths}
          midRails={activeMidRails}
        />
      )}
    </group>
  );
}

