import { pgTable, text, serial, integer, boolean, timestamp, jsonb, real } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

export const users = pgTable("users", {
  id: serial("id").primaryKey(),
  username: text("username").notNull().unique(),
  password: text("password").notNull(),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

export const doorConfigs = pgTable("door_configs", {
  id: serial("id").primaryKey(),
  userId: integer("user_id").references(() => users.id),
  width: integer("width").notNull(),
  height: integer("height").notNull(),
  thickness: integer("thickness").notNull(),
  mainHeight: integer("main_height").notNull(),
  secondaryHeight: integer("secondary_height").notNull(),
  topWidth: integer("top_width").notNull(),
  preset: text("preset").notNull(),
  panelType: text("panel_type").notNull(),
  panelCount: integer("panel_count").notNull(),
  borderHeightTop: integer("border_height_top").notNull(),
  borderHeightBottom: integer("border_height_bottom").notNull(),
  borderStyle: text("border_style").notNull(),
  basePrice: real("base_price").notNull(),
  price: real("price").notNull(),
  material: text("material"),
  finish: text("finish"),
  color: text("color"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});

export const cartItems = pgTable("cart_items", {
  id: serial("id").primaryKey(),
  userId: integer("user_id").references(() => users.id),
  doorConfigId: integer("door_config_id").references(() => doorConfigs.id),
  quantity: integer("quantity").notNull().default(1),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

export const orders = pgTable("orders", {
  id: serial("id").primaryKey(),
  userId: integer("user_id").references(() => users.id).notNull(),
  totalPrice: real("total_price").notNull(),
  status: text("status").notNull().default("pending"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});

export const orderItems = pgTable("order_items", {
  id: serial("id").primaryKey(),
  orderId: integer("order_id").references(() => orders.id).notNull(),
  doorConfigData: jsonb("door_config_data").notNull(),
  quantity: integer("quantity").notNull().default(1),
  priceAtOrder: real("price_at_order").notNull(),
});

export const insertUserSchema = createInsertSchema(users).pick({
  username: true,
  password: true,
});

export type InsertUser = z.infer<typeof insertUserSchema>;
export type User = typeof users.$inferSelect;
export type DoorConfig = typeof doorConfigs.$inferSelect;
export type InsertDoorConfig = typeof doorConfigs.$inferInsert;
export type CartItem = typeof cartItems.$inferSelect;
export type InsertCartItem = typeof cartItems.$inferInsert;
export type Order = typeof orders.$inferSelect;
export type InsertOrder = typeof orders.$inferInsert;
export type OrderItem = typeof orderItems.$inferSelect;
export type InsertOrderItem = typeof orderItems.$inferInsert;

