import { useState } from "react";
import { useDoorConfig } from "@/lib/stores/useDoorConfig";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { Download, Plus, X } from "lucide-react";
import { cn } from "@/lib/utils";

interface ConfigSidebarProps {
  isMobile?: boolean;
  onClose?: () => void;
}

export function ConfigSidebar({ isMobile = false }: ConfigSidebarProps) {
  const config = useDoorConfig();
  const [savedMessage, setSavedMessage] = useState("");
  const [isLoading, setIsLoading] = useState(false);

  const handleExportDxf = async () => {
    setIsLoading(true);
    try {
      const exportConfig = {
        width: config.width,
        height: config.height,
        thickness: config.thickness,
        mainHeight: config.mainHeight,
        topWidth: config.topWidth,
        preset: config.preset,
        panelType: config.panelType,
        panelCount: config.panelCount,
        shape: config.shape,
        railPosition: config.railPosition,
        railHeights: config.railHeights,
        borderHeight: config.borderHeight,
        borderStyle: config.borderStyle,
        material: config.material,
        finish: config.finish,
        color: config.color,
      };

      const response = await fetch("/api/export/dxf", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(exportConfig),
      });

      if (!response.ok) {
        throw new Error("Failed to generate DXF file");
      }

      const blob = await response.blob();
      const filename = response.headers.get("Content-Disposition")?.split("filename=")[1]?.replace(/"/g, "") || `door-${config.preset}-${config.width}x${config.mainHeight}.dxf`;

      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);

      setSavedMessage("DXF file downloaded!");
    } catch (error) {
      setSavedMessage("Error generating DXF file");
      console.error(error);
    } finally {
      setIsLoading(false);
      setTimeout(() => setSavedMessage(""), 3000);
    }
  };

  const handleExportSvg = async () => {
    setIsLoading(true);
    try {
      const exportConfig = {
        width: config.width,
        height: config.height,
        thickness: config.thickness,
        mainHeight: config.mainHeight,
        topWidth: config.topWidth,
        preset: config.preset,
        panelType: config.panelType,
        panelCount: config.panelCount,
        shape: config.shape,
        angledLeft: config.angledLeft,
        angledRight: config.angledRight,
        leftTriangleCutoutWidth: config.leftTriangleCutoutWidth,
        leftTriangleCutoutHeight: config.leftTriangleCutoutHeight,
        rightTriangleCutoutWidth: config.rightTriangleCutoutWidth,
        rightTriangleCutoutHeight: config.rightTriangleCutoutHeight,
        borderWidth: config.borderWidth,
        customBorders: config.customBorders,
        leftStile: config.leftStile,
        rightStile: config.rightStile,
        bottomRail: config.bottomRail,
        topRail: config.topRail,
        midRailsEnabled: config.midRailsEnabled,
        midRails: config.midRails,
        borderHeight: config.borderHeight,
        borderStyle: config.borderStyle,
        material: config.material,
        finish: config.finish,
        color: config.color,
      };

      const response = await fetch("/api/export/svg", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(exportConfig),
      });

      if (!response.ok) {
        throw new Error("Failed to generate SVG file");
      }

      const blob = await response.blob();
      const filename = response.headers.get("Content-Disposition")?.split("filename=")[1]?.replace(/"/g, "") || `door-${config.preset}-${config.width}x${config.mainHeight}.svg`;

      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);

      setSavedMessage("SVG file downloaded!");
    } catch (error) {
      setSavedMessage("Error generating SVG file");
      console.error(error);
    } finally {
      setIsLoading(false);
      setTimeout(() => setSavedMessage(""), 3000);
    }
  };

  return (
    <div className={cn(
      "w-full h-full bg-white flex flex-col shadow-lg",
      !isMobile && "md:w-96 border-l border-gray-200"
    )}>
      <div className="p-4 md:p-6 border-b border-gray-100 bg-white">
        <h1 className="text-base md:text-xl font-semibold text-gray-900">Door Configurator</h1>
        <p className="text-2xl md:text-4xl font-bold text-gray-900 mt-2 md:mt-3">
          £ {config.price.toFixed(2)}
          <span className="text-xs md:text-sm font-normal text-gray-600 ml-2">(excl VAT)</span>
        </p>
      </div>

      <div className="p-4 md:p-6 border-b border-gray-100">
        <div className="flex gap-3">
          <Button
            onClick={handleExportSvg}
            variant="outline"
            className="flex-1 bg-green-500 hover:bg-green-600 text-white border-none text-sm md:text-base font-medium shadow-sm"
            disabled={isLoading}
          >
            <Download className="w-4 h-4 mr-2" />
            SVG
          </Button>
          <Button
            onClick={handleExportDxf}
            variant="outline"
            className="flex-1 bg-blue-500 hover:bg-blue-600 text-white border-none text-sm md:text-base font-medium shadow-sm"
            disabled={isLoading}
          >
            <Download className="w-4 h-4 mr-2" />
            DXF
          </Button>
        </div>

        {savedMessage && (
          <p className="text-xs md:text-sm text-green-600 mt-3 text-center font-medium">{savedMessage}</p>
        )}
      </div>

      <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-6">
        <DoorDimensionsSection />
        <AngledCornersSection />
        <BorderWidthsSection />
        <MidRailsSection />
        <HingePositionsSection />
      </div>
    </div>
  );
}

function DoorDimensionsSection() {
  const { height, width, setHeight, setWidth } = useDoorConfig();

  return (
    <div className="space-y-4">
      <h3 className="text-blue-600 font-semibold text-sm">Door Dimensions</h3>

      <div className="space-y-1">
        <Label className="text-sm text-gray-600">Height (mm)</Label>
        <Input
          type="number"
          value={height}
          onChange={(e) => setHeight(Number(e.target.value))}
          className="w-full"
        />
        <span className="text-xs text-gray-400">200-2430mm</span>
      </div>

      <div className="space-y-1">
        <Label className="text-sm text-gray-600">Width (mm)</Label>
        <Input
          type="number"
          value={width}
          onChange={(e) => setWidth(Number(e.target.value))}
          className="w-full"
        />
        <span className="text-xs text-gray-400">200-900mm</span>
      </div>
    </div>
  );
}

function AngledCornersSection() {
  const {
    angledLeft,
    angledRight,
    leftTriangleCutoutWidth,
    leftTriangleCutoutHeight,
    rightTriangleCutoutWidth,
    rightTriangleCutoutHeight,
    setAngledLeft,
    setAngledRight,
    setLeftTriangleCutoutWidth,
    setLeftTriangleCutoutHeight,
    setRightTriangleCutoutWidth,
    setRightTriangleCutoutHeight,
  } = useDoorConfig();

  return (
    <div className="space-y-4">
      <h3 className="text-blue-600 font-semibold text-sm">Angled Corners</h3>

      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <Label className="text-sm text-gray-600">Angled Left</Label>
          <Switch checked={angledLeft} onCheckedChange={setAngledLeft} />
        </div>

        {angledLeft && (
          <div className="pl-4 space-y-3 border-l-2 border-blue-200">
            <div className="flex items-center justify-between">
              <Label className="text-sm text-gray-500">Left triangle cutout width:</Label>
              <Input
                type="number"
                value={leftTriangleCutoutWidth}
                onChange={(e) => setLeftTriangleCutoutWidth(Number(e.target.value))}
                className="w-20 text-right"
              />
            </div>
            <div className="flex items-center justify-between">
              <Label className="text-sm text-gray-500">Left triangle cutout height:</Label>
              <Input
                type="number"
                value={leftTriangleCutoutHeight}
                onChange={(e) => setLeftTriangleCutoutHeight(Number(e.target.value))}
                className="w-20 text-right"
              />
            </div>
          </div>
        )}
      </div>

      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <Label className="text-sm text-gray-600">Angled Right</Label>
          <Switch checked={angledRight} onCheckedChange={setAngledRight} />
        </div>

        {angledRight && (
          <div className="pl-4 space-y-3 border-l-2 border-blue-200">
            <div className="flex items-center justify-between">
              <Label className="text-sm text-gray-500">Right triangle cutout width:</Label>
              <Input
                type="number"
                value={rightTriangleCutoutWidth}
                onChange={(e) => setRightTriangleCutoutWidth(Number(e.target.value))}
                className="w-20 text-right"
              />
            </div>
            <div className="flex items-center justify-between">
              <Label className="text-sm text-gray-500">Right triangle cutout height:</Label>
              <Input
                type="number"
                value={rightTriangleCutoutHeight}
                onChange={(e) => setRightTriangleCutoutHeight(Number(e.target.value))}
                className="w-20 text-right"
              />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function BorderWidthsSection() {
  const {
    borderWidth,
    customBorders,
    leftStile,
    rightStile,
    bottomRail,
    topRail,
    setBorderWidth,
    setCustomBorders,
    setLeftStile,
    setRightStile,
    setBottomRail,
    setTopRail,
  } = useDoorConfig();

  return (
    <div className="space-y-4">
      <h3 className="text-blue-600 font-semibold text-sm">Border Widths</h3>

      <div className="space-y-1">
        <Label className="text-sm text-gray-600">Border width (mm)</Label>
        <Input
          type="number"
          value={borderWidth}
          onChange={(e) => setBorderWidth(Number(e.target.value))}
          className="w-full"
          disabled={customBorders}
        />
        <span className="text-xs text-gray-400">60-150mm</span>
      </div>

      <div className="flex items-center justify-between">
        <Label className="text-sm text-gray-600">Custom</Label>
        <Switch checked={customBorders} onCheckedChange={setCustomBorders} />
      </div>

      {customBorders && (
        <div className="space-y-3 pl-4 border-l-2 border-blue-200">
          <div className="flex items-center justify-between">
            <Label className="text-sm text-gray-500">Left stile:</Label>
            <Input
              type="number"
              value={leftStile}
              onChange={(e) => setLeftStile(Number(e.target.value))}
              className="w-20 text-right"
            />
          </div>
          <div className="flex items-center justify-between">
            <Label className="text-sm text-gray-500">Right stile:</Label>
            <Input
              type="number"
              value={rightStile}
              onChange={(e) => setRightStile(Number(e.target.value))}
              className="w-20 text-right"
            />
          </div>
          <div className="flex items-center justify-between">
            <Label className="text-sm text-gray-500">Bottom rail:</Label>
            <Input
              type="number"
              value={bottomRail}
              onChange={(e) => setBottomRail(Number(e.target.value))}
              className="w-20 text-right"
            />
          </div>
          <div className="flex items-center justify-between">
            <Label className="text-sm text-gray-500">Top rail:</Label>
            <Input
              type="number"
              value={topRail}
              onChange={(e) => setTopRail(Number(e.target.value))}
              className="w-20 text-right"
            />
          </div>
        </div>
      )}
    </div>
  );
}

function MidRailsSection() {
  const {
    midRailsEnabled,
    midRailsEqualise,
    midRails,
    setMidRailsEnabled,
    setMidRailsEqualise,
    addMidRail,
    removeMidRail,
    updateMidRail,
  } = useDoorConfig();

  return (
    <div className="space-y-4">
      <h3 className="text-blue-600 font-semibold text-sm">Mid Rails</h3>

      <div className="flex items-center justify-between">
        <Label className="text-sm text-gray-600">Mid Rails</Label>
        <Switch checked={midRailsEnabled} onCheckedChange={setMidRailsEnabled} />
      </div>

      {midRailsEnabled && (
        <>
          <div className="flex items-center justify-between">
            <Label className="text-sm text-gray-600">Equalise</Label>
            <Switch checked={midRailsEqualise} onCheckedChange={setMidRailsEqualise} />
          </div>

          <div className="space-y-4">
            {midRails.map((rail, index) => (
              <div key={rail.id} className="p-3 bg-gray-50 rounded-lg space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-sm font-medium text-gray-700">Mid rail {midRails.length - index}:</span>
                  <Button
                    variant="destructive"
                    size="sm"
                    onClick={() => removeMidRail(rail.id)}
                    className="h-7 px-2 text-xs"
                  >
                    Remove
                  </Button>
                </div>

                <div className="flex items-center justify-between">
                  <Label className="text-sm text-gray-500">Position from bottom of door:</Label>
                  <Input
                    type="number"
                    value={rail.positionFromBottom}
                    onChange={(e) => updateMidRail(rail.id, 'positionFromBottom', Number(e.target.value))}
                    className="w-20 text-right"
                  />
                </div>

                <div className="flex items-center justify-between">
                  <Label className="text-sm text-gray-500">Midrail dimension:</Label>
                  <Input
                    type="number"
                    value={rail.dimension}
                    onChange={(e) => updateMidRail(rail.id, 'dimension', Number(e.target.value))}
                    className="w-20 text-right"
                  />
                </div>
              </div>
            ))}
          </div>

          <Button
            variant="outline"
            size="sm"
            onClick={addMidRail}
            className="w-full"
          >
            <Plus className="w-4 h-4 mr-2" />
            Add Mid Rail
          </Button>
        </>
      )}
    </div>
  );
}

function HingePositionsSection() {
  const { hingeDrilling, setHingeDrilling } = useDoorConfig();

  return (
    <div className="space-y-4">
      <h3 className="text-blue-600 font-semibold text-sm">Hinge Positions</h3>

      <div className="flex items-center justify-between">
        <Label className="text-sm text-gray-600">Hinge Drilling</Label>
        <Switch checked={hingeDrilling} onCheckedChange={setHingeDrilling} />
      </div>
    </div>
  );
}

