export interface SvgDoorConfig {
  width: number;
  height: number;
  thickness: number;
  mainHeight: number;
  topWidth: number;
  preset: string;
  panelType: string;
  panelCount: number;
  shape: string;
  angledLeft?: boolean;
  angledRight?: boolean;
  leftTriangleCutoutWidth?: number;
  leftTriangleCutoutHeight?: number;
  rightTriangleCutoutWidth?: number;
  rightTriangleCutoutHeight?: number;
  borderWidth: number;
  customBorders?: boolean;
  leftStile?: number;
  rightStile?: number;
  bottomRail?: number;
  topRail?: number;
  midRailsEnabled?: boolean;
  midRails?: Array<{ positionFromBottom: number; dimension: number }>;
  borderHeight: {
    top: number;
    bottom: number;
  };
  borderStyle: string;
  material: string;
  finish: string;
  color: string;
}

export function generateDoorSvg(config: SvgDoorConfig): string {
  const {
    width,
    mainHeight,
    preset,
    panelType,
    panelCount,
    shape,
    angledLeft = false,
    angledRight = false,
    leftTriangleCutoutWidth = 100,
    leftTriangleCutoutHeight = 200,
    rightTriangleCutoutWidth = 100,
    rightTriangleCutoutHeight = 200,
    borderWidth = 75,
    customBorders = false,
    leftStile = borderWidth,
    rightStile = borderWidth,
    bottomRail = borderWidth,
    topRail = borderWidth,
    midRailsEnabled = false,
    midRails = [],
    borderStyle,
  } = config;

  const h = mainHeight;
  const w = width;
  const isDoubleDoor = preset === "double";

  const padding = 80;
  const svgWidth = w + padding * 2;
  const svgHeight = h + padding * 2 + 60;

  const strokeWidth = 2;
  const strokeColor = "#333333";
  const fillColor = "#f5f0e8";
  const panelFillColor = "#e8e0d0";
  const railFillColor = "#d4cbbf";

  let svg = `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${svgWidth} ${svgHeight}" width="${svgWidth}" height="${svgHeight}">
  <defs>
    <style>
      .frame { fill: ${fillColor}; stroke: ${strokeColor}; stroke-width: ${strokeWidth}; }
      .panel { fill: ${panelFillColor}; stroke: ${strokeColor}; stroke-width: ${strokeWidth * 0.75}; }
      .rail { fill: ${railFillColor}; stroke: ${strokeColor}; stroke-width: ${strokeWidth * 0.5}; }
      .dimension { font-family: Arial, sans-serif; font-size: 12px; fill: #666; }
      .title { font-family: Arial, sans-serif; font-size: 14px; font-weight: bold; fill: #333; }
    </style>
  </defs>
`;

  const transformY = (y: number) => h - y + padding;

  if (isDoubleDoor) {
    const gap = 10;
    const leafWidth = (w - gap) / 2;

    svg += drawDoorLeaf(
      padding,
      leafWidth,
      h,
      shape,
      angledLeft,
      false,
      leftTriangleCutoutWidth,
      leftTriangleCutoutHeight,
      0,
      0,
      panelType,
      panelCount,
      leftStile,
      rightStile,
      bottomRail,
      topRail,
      midRailsEnabled,
      midRails,
      borderStyle,
      transformY
    );

    svg += drawDoorLeaf(
      padding + leafWidth + gap,
      leafWidth,
      h,
      shape,
      false,
      angledRight,
      0,
      0,
      rightTriangleCutoutWidth,
      rightTriangleCutoutHeight,
      panelType,
      panelCount,
      leftStile,
      rightStile,
      bottomRail,
      topRail,
      midRailsEnabled,
      midRails,
      borderStyle,
      transformY
    );
  } else {
    svg += drawDoorLeaf(
      padding,
      w,
      h,
      shape,
      angledLeft,
      angledRight,
      leftTriangleCutoutWidth,
      leftTriangleCutoutHeight,
      rightTriangleCutoutWidth,
      rightTriangleCutoutHeight,
      panelType,
      panelCount,
      leftStile,
      rightStile,
      bottomRail,
      topRail,
      midRailsEnabled,
      midRails,
      borderStyle,
      transformY
    );
  }

  svg += addDimensions(padding, w, h, isDoubleDoor, transformY);
  svg += addTitleBlock(padding, svgHeight, config);
  svg += `</svg>`;

  return svg;
}

function drawDoorLeaf(
  xOffset: number,
  width: number,
  height: number,
  shape: string,
  angledLeft: boolean,
  angledRight: boolean,
  leftCutW: number,
  leftCutH: number,
  rightCutW: number,
  rightCutH: number,
  panelType: string,
  panelCount: number,
  leftStile: number,
  rightStile: number,
  bottomRail: number,
  topRail: number,
  midRailsEnabled: boolean,
  midRails: Array<{ positionFromBottom: number; dimension: number }>,
  borderStyle: string,
  transformY: (y: number) => number
): string {
  let svg = "";

  let pathD = "";
  if (angledLeft || angledRight) {
    const points: Array<[number, number]> = [];

    if (angledLeft) {
      points.push([xOffset + leftCutW, transformY(0)]);
      points.push([xOffset, transformY(leftCutH)]);
      points.push([xOffset, transformY(height)]);
    } else {
      points.push([xOffset, transformY(0)]);
      points.push([xOffset, transformY(height)]);
    }

    if (angledRight) {
      points.push([xOffset + width, transformY(height)]);
      points.push([xOffset + width, transformY(rightCutH)]);
      points.push([xOffset + width - rightCutW, transformY(0)]);
    } else {
      points.push([xOffset + width, transformY(height)]);
      points.push([xOffset + width, transformY(0)]);
    }

    pathD = `M ${points[0][0]} ${points[0][1]} `;
    for (let i = 1; i < points.length; i++) {
      pathD += `L ${points[i][0]} ${points[i][1]} `;
    }
    pathD += "Z";

    svg += `  <path class="frame" d="${pathD}" />\n`;
  } else {
    svg += `  <rect class="frame" x="${xOffset}" y="${transformY(height)}" width="${width}" height="${height}" />\n`;
  }

  if (midRailsEnabled && midRails.length > 0) {
    for (const rail of midRails) {
      const railY = transformY(rail.positionFromBottom + rail.dimension / 2);
      svg += `  <rect class="rail" x="${xOffset + leftStile}" y="${railY}" width="${width - leftStile - rightStile}" height="${rail.dimension}" />\n`;
    }
  }

  if (panelType !== "flat" && panelCount > 0) {
    const panelAreaWidth = width - leftStile - rightStile;
    const panelAreaHeight = height - bottomRail - topRail;

    let sections: Array<{ startY: number; endY: number }> = [];

    if (midRailsEnabled && midRails.length > 0) {
      const sortedRails = [...midRails].sort((a, b) => a.positionFromBottom - b.positionFromBottom);

      let lastY = bottomRail;
      for (const rail of sortedRails) {
        if (rail.positionFromBottom > lastY) {
          sections.push({ startY: lastY, endY: rail.positionFromBottom });
        }
        lastY = rail.positionFromBottom + rail.dimension;
      }
      if (lastY < height - topRail) {
        sections.push({ startY: lastY, endY: height - topRail });
      }
    } else {
      sections.push({ startY: bottomRail, endY: height - topRail });
    }

    for (const section of sections) {
      const sectionHeight = section.endY - section.startY;
      const panelPadding = 15;
      const panelWidth = (panelAreaWidth - panelPadding * (panelCount + 1)) / panelCount;
      const panelHeight = sectionHeight - panelPadding * 2;

      for (let i = 0; i < panelCount; i++) {
        const panelX = xOffset + leftStile + panelPadding + i * (panelWidth + panelPadding);
        const panelY = transformY(section.startY + panelPadding + panelHeight);

        if (panelType === "shaker") {
          svg += `  <rect class="panel" x="${panelX}" y="${panelY}" width="${panelWidth}" height="${panelHeight}" rx="2" />\n`;
        } else if (panelType === "raised") {
          svg += `  <rect class="panel" x="${panelX}" y="${panelY}" width="${panelWidth}" height="${panelHeight}" />\n`;
          const innerPad = 10;
          svg += `  <rect class="panel" x="${panelX + innerPad}" y="${panelY + innerPad}" width="${panelWidth - innerPad * 2}" height="${panelHeight - innerPad * 2}" />\n`;
        }
      }
    }
  }

  return svg;
}

function addDimensions(
  padding: number,
  width: number,
  height: number,
  isDoubleDoor: boolean,
  transformY: (y: number) => number
): string {
  let svg = "";

  const dimOffset = 30;

  svg += `  <line x1="${padding}" y1="${transformY(0) + dimOffset}" x2="${padding + width}" y2="${transformY(0) + dimOffset}" stroke="#999" stroke-width="1" />\n`;
  svg += `  <line x1="${padding}" y1="${transformY(0) + dimOffset - 5}" x2="${padding}" y2="${transformY(0) + dimOffset + 5}" stroke="#999" stroke-width="1" />\n`;
  svg += `  <line x1="${padding + width}" y1="${transformY(0) + dimOffset - 5}" x2="${padding + width}" y2="${transformY(0) + dimOffset + 5}" stroke="#999" stroke-width="1" />\n`;
  svg += `  <text class="dimension" x="${padding + width / 2}" y="${transformY(0) + dimOffset + 20}" text-anchor="middle">${Math.round(width)}mm</text>\n`;

  svg += `  <line x1="${padding - dimOffset}" y1="${transformY(0)}" x2="${padding - dimOffset}" y2="${transformY(height)}" stroke="#999" stroke-width="1" />\n`;
  svg += `  <line x1="${padding - dimOffset - 5}" y1="${transformY(0)}" x2="${padding - dimOffset + 5}" y2="${transformY(0)}" stroke="#999" stroke-width="1" />\n`;
  svg += `  <line x1="${padding - dimOffset - 5}" y1="${transformY(height)}" x2="${padding - dimOffset + 5}" y2="${transformY(height)}" stroke="#999" stroke-width="1" />\n`;
  svg += `  <text class="dimension" x="${padding - dimOffset - 10}" y="${transformY(height / 2)}" text-anchor="end" dominant-baseline="middle">${Math.round(height)}mm</text>\n`;

  return svg;
}

function addTitleBlock(padding: number, svgHeight: number, config: SvgDoorConfig): string {
  const y = svgHeight - 30;
  return `  <text class="title" x="${padding}" y="${y}">Door: ${config.width}mm x ${config.mainHeight}mm | ${config.preset} | ${config.panelType} panel | ${config.material}</text>\n`;
}

