import { useDoorConfig } from "@/lib/stores/useDoorConfig";

export function Door2D() {
  const config = useDoorConfig();

  const {
    width,
    height,
    panelType,
    panelCount,
    angledLeft,
    angledRight,
    leftTriangleCutoutWidth,
    leftTriangleCutoutHeight,
    rightTriangleCutoutWidth,
    rightTriangleCutoutHeight,
    leftStile,
    rightStile,
    bottomRail,
    topRail,
    midRailsEnabled,
    midRails,
    showDimensions,
  } = config;

  const padding = 80;
  const maxWidth = 500;
  const maxHeight = 650;

  const scaleX = (maxWidth - padding * 2) / width;
  const scaleY = (maxHeight - padding * 2) / height;
  const scale = Math.min(scaleX, scaleY);

  const scaledWidth = width * scale;
  const scaledHeight = height * scale;

  const offsetX = (maxWidth - scaledWidth) / 2;
  const offsetY = (maxHeight - scaledHeight) / 2;

  const strokeColor = "#333333";
  const fillColor = "#f5e6d3";
  const panelFillColor = "#e8dcc8";
  const railFillColor = "#d4c4a8";
  const dimensionColor = "#666666";

  const toSvgX = (x: number) => offsetX + x * scale;
  const toSvgY = (y: number) => offsetY + (height - y) * scale;

  const getDoorOutline = () => {
    const points: string[] = [];

    if (angledLeft) {
      points.push(`${toSvgX(leftTriangleCutoutWidth)},${toSvgY(0)}`);
      points.push(`${toSvgX(0)},${toSvgY(leftTriangleCutoutHeight)}`);
      points.push(`${toSvgX(0)},${toSvgY(height)}`);
    } else {
      points.push(`${toSvgX(0)},${toSvgY(0)}`);
      points.push(`${toSvgX(0)},${toSvgY(height)}`);
    }

    if (angledRight) {
      points.push(`${toSvgX(width)},${toSvgY(height)}`);
      points.push(`${toSvgX(width)},${toSvgY(rightTriangleCutoutHeight)}`);
      points.push(`${toSvgX(width - rightTriangleCutoutWidth)},${toSvgY(0)}`);
    } else {
      points.push(`${toSvgX(width)},${toSvgY(height)}`);
      points.push(`${toSvgX(width)},${toSvgY(0)}`);
    }

    return points.join(" ");
  };

  const renderMidRails = () => {
    if (!midRailsEnabled || midRails.length === 0) return null;

    return midRails.map((rail) => {
      const railY = rail.positionFromBottom;
      const railHeight = rail.dimension;

      return (
        <rect
          key={rail.id}
          x={toSvgX(leftStile)}
          y={toSvgY(railY + railHeight)}
          width={(width - leftStile - rightStile) * scale}
          height={railHeight * scale}
          fill={railFillColor}
          stroke={strokeColor}
          strokeWidth={1}
        />
      );
    });
  };

  const renderPanels = () => {
    if (panelType === "flat" || panelCount === 0) return null;

    let sections: Array<{ startY: number; endY: number }> = [];

    if (midRailsEnabled && midRails.length > 0) {
      const sortedRails = [...midRails].sort((a, b) => a.positionFromBottom - b.positionFromBottom);

      let lastY = bottomRail;
      for (const rail of sortedRails) {
        if (rail.positionFromBottom > lastY) {
          sections.push({ startY: lastY, endY: rail.positionFromBottom });
        }
        lastY = rail.positionFromBottom + rail.dimension;
      }
      if (lastY < height - topRail) {
        sections.push({ startY: lastY, endY: height - topRail });
      }
    } else {
      sections.push({ startY: bottomRail, endY: height - topRail });
    }

    const panels: JSX.Element[] = [];
    const panelPadding = 15;
    const panelAreaWidth = width - leftStile - rightStile;
    const panelWidth = (panelAreaWidth - panelPadding * (panelCount + 1)) / panelCount;

    sections.forEach((section, sectionIdx) => {
      const sectionHeight = section.endY - section.startY;
      const panelHeight = sectionHeight - panelPadding * 2;

      for (let i = 0; i < panelCount; i++) {
        const panelX = leftStile + panelPadding + i * (panelWidth + panelPadding);
        const panelY = section.startY + panelPadding;

        if (panelType === "shaker") {
          panels.push(
            <rect
              key={`panel-${sectionIdx}-${i}`}
              x={toSvgX(panelX)}
              y={toSvgY(panelY + panelHeight)}
              width={panelWidth * scale}
              height={panelHeight * scale}
              fill={panelFillColor}
              stroke={strokeColor}
              strokeWidth={1}
              rx={2}
            />
          );
        } else if (panelType === "raised") {
          panels.push(
            <g key={`panel-${sectionIdx}-${i}`}>
              <rect
                x={toSvgX(panelX)}
                y={toSvgY(panelY + panelHeight)}
                width={panelWidth * scale}
                height={panelHeight * scale}
                fill={panelFillColor}
                stroke={strokeColor}
                strokeWidth={1}
              />
              <rect
                x={toSvgX(panelX + 10)}
                y={toSvgY(panelY + panelHeight - 10)}
                width={(panelWidth - 20) * scale}
                height={(panelHeight - 20) * scale}
                fill={panelFillColor}
                stroke={strokeColor}
                strokeWidth={0.5}
              />
            </g>
          );
        }
      }
    });

    return panels;
  };

  const renderDimensions = () => {
    if (!showDimensions) return null;

    const dimOffset = 20;

    return (
      <>
        <line
          x1={toSvgX(0)}
          y1={toSvgY(0) + dimOffset}
          x2={toSvgX(width)}
          y2={toSvgY(0) + dimOffset}
          stroke={dimensionColor}
          strokeWidth={1}
        />
        <line
          x1={toSvgX(0)}
          y1={toSvgY(0) + dimOffset - 5}
          x2={toSvgX(0)}
          y2={toSvgY(0) + dimOffset + 5}
          stroke={dimensionColor}
          strokeWidth={1}
        />
        <line
          x1={toSvgX(width)}
          y1={toSvgY(0) + dimOffset - 5}
          x2={toSvgX(width)}
          y2={toSvgY(0) + dimOffset + 5}
          stroke={dimensionColor}
          strokeWidth={1}
        />
        <text
          x={toSvgX(width / 2)}
          y={toSvgY(0) + dimOffset + 15}
          textAnchor="middle"
          fill={dimensionColor}
          fontSize="12"
          fontFamily="Arial, sans-serif"
        >
          {width}mm
        </text>

        <line
          x1={toSvgX(0) - dimOffset}
          y1={toSvgY(0)}
          x2={toSvgX(0) - dimOffset}
          y2={toSvgY(height)}
          stroke={dimensionColor}
          strokeWidth={1}
        />
        <line
          x1={toSvgX(0) - dimOffset - 5}
          y1={toSvgY(0)}
          x2={toSvgX(0) - dimOffset + 5}
          y2={toSvgY(0)}
          stroke={dimensionColor}
          strokeWidth={1}
        />
        <line
          x1={toSvgX(0) - dimOffset - 5}
          y1={toSvgY(height)}
          x2={toSvgX(0) - dimOffset + 5}
          y2={toSvgY(height)}
          stroke={dimensionColor}
          strokeWidth={1}
        />
        <text
          x={toSvgX(0) - dimOffset - 8}
          y={toSvgY(height / 2)}
          textAnchor="end"
          dominantBaseline="middle"
          fill={dimensionColor}
          fontSize="12"
          fontFamily="Arial, sans-serif"
        >
          {height}mm
        </text>
      </>
    );
  };

  return (
    <div className="w-full h-full flex items-center justify-center bg-gradient-to-b from-gray-50 to-gray-100">
      <svg
        viewBox={`0 0 ${maxWidth} ${maxHeight}`}
        className="max-w-full max-h-full"
        style={{ width: "100%", height: "100%" }}
      >
        <polygon
          points={getDoorOutline()}
          fill={fillColor}
          stroke={strokeColor}
          strokeWidth={2}
        />

        {renderMidRails()}
        {renderPanels()}
        {renderDimensions()}

        <text
          x={maxWidth / 2}
          y={maxHeight - 10}
          textAnchor="middle"
          fill="#999"
          fontSize="11"
          fontFamily="Arial, sans-serif"
        >
          {width}mm x {height}mm | {panelType} panel
        </text>
      </svg>
    </div>
  );
}

