import { DxfWriter, point3d, point2d, LWPolylineFlags } from "@tarikjabiri/dxf";

export interface DxfDoorConfig {
  width: number;
  height: number;
  thickness: number;
  mainHeight: number;
  topWidth: number;
  preset: string;
  panelType: string;
  panelCount: number;
  shape: string;
  railPosition: {
    top: number;
    middle: number;
  };
  railHeights: {
    top: number;
    middle: number;
  };
  borderHeight: {
    top: number;
    bottom: number;
  };
  borderStyle: string;
  material: string;
  finish: string;
  color: string;
}

export function generateDoorDxf(config: DxfDoorConfig): string {
  const dxf = new DxfWriter();

  const {
    width,
    mainHeight,
    thickness,
    topWidth,
    preset,
    panelType,
    panelCount,
    shape,
    railPosition,
    railHeights,
    borderHeight,
    borderStyle,
  } = config;

  const h = mainHeight;
  const w = width;
  const wTop = shape === "angled" ? topWidth : width;
  const isDoubleDoor = preset === "double";

  dxf.addLayer("FRAME", 7, "CONTINUOUS");
  dxf.addLayer("PANELS", 7, "CONTINUOUS");
  dxf.addLayer("BORDERS", 7, "CONTINUOUS");
  dxf.addLayer("RAILS", 7, "CONTINUOUS");
  dxf.addLayer("HANDLES", 7, "CONTINUOUS");
  dxf.addLayer("DIMENSIONS", 7, "CONTINUOUS");
  dxf.addLayer("CENTER_LINES", 7, "CONTINUOUS");

  if (isDoubleDoor) {
    const gap = 10;
    const leafWidth = (w - gap) / 2;
    const leafTopWidth = shape === "angled" ? (wTop - gap) / 2 : leafWidth;

    drawDoorLeaf(dxf, -leafWidth - gap/2, 0, leafWidth, h, leafTopWidth, shape, panelType, panelCount, borderHeight, borderStyle, railPosition, railHeights, false, thickness);
    drawDoorLeaf(dxf, gap/2, 0, leafWidth, h, leafTopWidth, shape, panelType, panelCount, borderHeight, borderStyle, railPosition, railHeights, true, thickness);

    addDimensionAnnotations(dxf, w, h, thickness, isDoubleDoor, shape, wTop);
  } else {
    drawDoorLeaf(dxf, -w/2, 0, w, h, wTop, shape, panelType, panelCount, borderHeight, borderStyle, railPosition, railHeights, false, thickness);
    addDimensionAnnotations(dxf, w, h, thickness, isDoubleDoor, shape, wTop);
  }

  addTitleBlock(dxf, config);

  return dxf.stringify();
}

function getWidthAtHeight(baseWidth: number, topWidth: number, height: number, totalHeight: number, shape: string): number {
  if (shape !== "angled") return baseWidth;
  const widthDiff = baseWidth - topWidth;
  const ratio = height / totalHeight;
  return baseWidth - (widthDiff * ratio);
}

function getOffsetAtHeight(baseWidth: number, topWidth: number, height: number, totalHeight: number, shape: string): number {
  if (shape !== "angled") return 0;
  const widthDiff = baseWidth - topWidth;
  const ratio = height / totalHeight;
  return (widthDiff * ratio) / 2;
}

function drawDoorLeaf(
  dxf: DxfWriter,
  xOffset: number,
  yOffset: number,
  width: number,
  height: number,
  topWidth: number,
  shape: string,
  panelType: string,
  panelCount: number,
  borderHeight: { top: number; bottom: number },
  borderStyle: string,
  railPosition: { top: number; middle: number },
  railHeights: { top: number; middle: number },
  mirrorHandle: boolean,
  thickness: number
) {
  if (shape === "angled") {
    const leftOffset = (width - topWidth) / 2;
    dxf.addLWPolyline([
      { point: point2d(xOffset, yOffset) },
      { point: point2d(xOffset + width, yOffset) },
      { point: point2d(xOffset + width - leftOffset, yOffset + height) },
      { point: point2d(xOffset + leftOffset, yOffset + height) },
    ], { flags: LWPolylineFlags.Closed, layerName: "FRAME" });
  } else {
    dxf.addRectangle(
      point2d(xOffset, yOffset + height),
      point2d(xOffset + width, yOffset),
      { layerName: "FRAME" }
    );
  }

  dxf.addLine(
    point3d(xOffset + width/2, yOffset - 20, 0),
    point3d(xOffset + width/2, yOffset + height + 20, 0),
    { layerName: "CENTER_LINES" }
  );
  dxf.addLine(
    point3d(xOffset - 20, yOffset + height/2, 0),
    point3d(xOffset + width + 20, yOffset + height/2, 0),
    { layerName: "CENTER_LINES" }
  );

  if (panelType !== "flat" && panelCount > 0) {
    drawPanels(dxf, xOffset, yOffset, width, height, topWidth, shape, panelType, panelCount, borderHeight, railPosition, railHeights);
  }

  if (borderStyle !== "none") {
    drawBorders(dxf, xOffset, yOffset, width, height, topWidth, shape, borderHeight, borderStyle);
  }

  if (railPosition.top > 0 || railPosition.middle > 0) {
    drawRails(dxf, xOffset, yOffset, width, height, topWidth, shape, railPosition, railHeights, panelCount);
  }

  drawHandle(dxf, xOffset, yOffset, width, height, mirrorHandle, thickness);
}

function drawPanels(
  dxf: DxfWriter,
  xOffset: number,
  yOffset: number,
  width: number,
  height: number,
  topWidth: number,
  shape: string,
  panelType: string,
  panelCount: number,
  borderHeight: { top: number; bottom: number },
  railPosition: { top: number; middle: number },
  railHeights: { top: number; middle: number }
) {
  const stileWidth = Math.max(40, width * 0.1);
  const bottomRailHeight = railHeights.middle > 0 ? railHeights.middle : 60;
  const topRailHeight = railHeights.top > 0 ? railHeights.top : 60;

  const contentBottom = yOffset + borderHeight.bottom + bottomRailHeight;
  const contentTop = yOffset + height - borderHeight.top - topRailHeight;
  const availableHeight = contentTop - contentBottom;

  const middleRailThickness = railPosition.middle !== 0 ? railHeights.middle : 0;

  const totalRailSpace = middleRailThickness * Math.max(0, panelCount - 1);
  const panelHeight = (availableHeight - totalRailSpace) / panelCount;

  for (let i = 0; i < panelCount; i++) {
    const panelBottom = contentBottom + i * (panelHeight + middleRailThickness);
    const panelTop = panelBottom + panelHeight;

    const bottomOffset = getOffsetAtHeight(width, topWidth, panelBottom - yOffset, height, shape);
    const topOffset = getOffsetAtHeight(width, topWidth, panelTop - yOffset, height, shape);

    const panelLeftBottom = xOffset + stileWidth + bottomOffset;
    const panelRightBottom = xOffset + width - stileWidth - bottomOffset;
    const panelLeftTop = xOffset + stileWidth + topOffset;
    const panelRightTop = xOffset + width - stileWidth - topOffset;

    if (shape === "angled") {
      dxf.addLWPolyline([
        { point: point2d(panelLeftBottom, panelBottom) },
        { point: point2d(panelRightBottom, panelBottom) },
        { point: point2d(panelRightTop, panelTop) },
        { point: point2d(panelLeftTop, panelTop) },
      ], { flags: LWPolylineFlags.Closed, layerName: "PANELS" });

      if (panelType === "shaker" || panelType === "raised") {
        const inset = panelType === "shaker" ? 30 : 40;
        const innerBottomOffset = getOffsetAtHeight(width, topWidth, panelBottom + inset - yOffset, height, shape);
        const innerTopOffset = getOffsetAtHeight(width, topWidth, panelTop - inset - yOffset, height, shape);

        dxf.addLWPolyline([
          { point: point2d(panelLeftBottom + inset - bottomOffset + innerBottomOffset, panelBottom + inset) },
          { point: point2d(panelRightBottom - inset + bottomOffset - innerBottomOffset, panelBottom + inset) },
          { point: point2d(panelRightTop - inset + topOffset - innerTopOffset, panelTop - inset) },
          { point: point2d(panelLeftTop + inset - topOffset + innerTopOffset, panelTop - inset) },
        ], { flags: LWPolylineFlags.Closed, layerName: "PANELS" });
      }
    } else {
      dxf.addRectangle(
        point2d(panelLeftBottom, panelTop),
        point2d(panelRightBottom, panelBottom),
        { layerName: "PANELS" }
      );

      if (panelType === "shaker") {
        const inset = 30;
        dxf.addRectangle(
          point2d(panelLeftBottom + inset, panelTop - inset),
          point2d(panelRightBottom - inset, panelBottom + inset),
          { layerName: "PANELS" }
        );
      } else if (panelType === "raised") {
        const inset = 40;
        dxf.addRectangle(
          point2d(panelLeftBottom + inset, panelTop - inset),
          point2d(panelRightBottom - inset, panelBottom + inset),
          { layerName: "PANELS" }
        );
        const innerInset = 60;
        dxf.addRectangle(
          point2d(panelLeftBottom + innerInset, panelTop - innerInset),
          point2d(panelRightBottom - innerInset, panelBottom + innerInset),
          { layerName: "PANELS" }
        );
      }
    }
  }
}

function drawBorders(
  dxf: DxfWriter,
  xOffset: number,
  yOffset: number,
  width: number,
  height: number,
  topWidth: number,
  shape: string,
  borderHeight: { top: number; bottom: number },
  borderStyle: string
) {
  const inset = 10;
  const detailInset = 20;

  if (borderHeight.bottom > 0) {
    dxf.addRectangle(
      point2d(xOffset + inset, yOffset + borderHeight.bottom),
      point2d(xOffset + width - inset, yOffset + inset),
      { layerName: "BORDERS" }
    );

    if (borderStyle === "detailed") {
      dxf.addRectangle(
        point2d(xOffset + detailInset, yOffset + borderHeight.bottom - inset),
        point2d(xOffset + width - detailInset, yOffset + detailInset),
        { layerName: "BORDERS" }
      );
    }
  }

  if (borderHeight.top > 0) {
    const topY = yOffset + height - borderHeight.top;

    if (shape === "angled") {
      const topOffset = getOffsetAtHeight(width, topWidth, height - borderHeight.top, height, shape);
      const fullTopOffset = getOffsetAtHeight(width, topWidth, height - inset, height, shape);

      dxf.addLWPolyline([
        { point: point2d(xOffset + inset + topOffset, topY) },
        { point: point2d(xOffset + width - inset - topOffset, topY) },
        { point: point2d(xOffset + width - inset - fullTopOffset, yOffset + height - inset) },
        { point: point2d(xOffset + inset + fullTopOffset, yOffset + height - inset) },
      ], { flags: LWPolylineFlags.Closed, layerName: "BORDERS" });

      if (borderStyle === "detailed") {
        const detailTopOffset = getOffsetAtHeight(width, topWidth, height - borderHeight.top + inset, height, shape);
        const detailFullTopOffset = getOffsetAtHeight(width, topWidth, height - detailInset, height, shape);

        dxf.addLWPolyline([
          { point: point2d(xOffset + detailInset + detailTopOffset, topY + inset) },
          { point: point2d(xOffset + width - detailInset - detailTopOffset, topY + inset) },
          { point: point2d(xOffset + width - detailInset - detailFullTopOffset, yOffset + height - detailInset) },
          { point: point2d(xOffset + detailInset + detailFullTopOffset, yOffset + height - detailInset) },
        ], { flags: LWPolylineFlags.Closed, layerName: "BORDERS" });
      }
    } else {
      dxf.addRectangle(
        point2d(xOffset + inset, yOffset + height - inset),
        point2d(xOffset + width - inset, topY),
        { layerName: "BORDERS" }
      );

      if (borderStyle === "detailed") {
        dxf.addRectangle(
          point2d(xOffset + detailInset, yOffset + height - detailInset),
          point2d(xOffset + width - detailInset, topY + inset),
          { layerName: "BORDERS" }
        );
      }
    }
  }
}

function drawRails(
  dxf: DxfWriter,
  xOffset: number,
  yOffset: number,
  width: number,
  height: number,
  topWidth: number,
  shape: string,
  railPosition: { top: number; middle: number },
  railHeights: { top: number; middle: number },
  panelCount: number
) {
  const stileWidth = Math.max(40, width * 0.1);

  if (railPosition.top > 0 && railHeights.top > 0) {
    const topRailY = yOffset + height - railPosition.top - railHeights.top / 2;
    const topRailYEnd = topRailY + railHeights.top;

    if (shape === "angled") {
      const bottomOffset = getOffsetAtHeight(width, topWidth, topRailY - yOffset, height, shape);
      const topOffset = getOffsetAtHeight(width, topWidth, topRailYEnd - yOffset, height, shape);

      dxf.addLWPolyline([
        { point: point2d(xOffset + stileWidth + bottomOffset, topRailY) },
        { point: point2d(xOffset + width - stileWidth - bottomOffset, topRailY) },
        { point: point2d(xOffset + width - stileWidth - topOffset, topRailYEnd) },
        { point: point2d(xOffset + stileWidth + topOffset, topRailYEnd) },
      ], { flags: LWPolylineFlags.Closed, layerName: "RAILS" });
    } else {
      dxf.addRectangle(
        point2d(xOffset + stileWidth, topRailYEnd),
        point2d(xOffset + width - stileWidth, topRailY),
        { layerName: "RAILS" }
      );
    }
  }

  if (railPosition.middle !== 0 && railHeights.middle > 0) {
    const middleRailY = yOffset + height / 2 - railHeights.middle / 2 + railPosition.middle;
    const middleRailYEnd = middleRailY + railHeights.middle;

    if (shape === "angled") {
      const bottomOffset = getOffsetAtHeight(width, topWidth, middleRailY - yOffset, height, shape);
      const topOffset = getOffsetAtHeight(width, topWidth, middleRailYEnd - yOffset, height, shape);

      dxf.addLWPolyline([
        { point: point2d(xOffset + stileWidth + bottomOffset, middleRailY) },
        { point: point2d(xOffset + width - stileWidth - bottomOffset, middleRailY) },
        { point: point2d(xOffset + width - stileWidth - topOffset, middleRailYEnd) },
        { point: point2d(xOffset + stileWidth + topOffset, middleRailYEnd) },
      ], { flags: LWPolylineFlags.Closed, layerName: "RAILS" });
    } else {
      dxf.addRectangle(
        point2d(xOffset + stileWidth, middleRailYEnd),
        point2d(xOffset + width - stileWidth, middleRailY),
        { layerName: "RAILS" }
      );
    }
  }
}

function drawHandle(
  dxf: DxfWriter,
  xOffset: number,
  yOffset: number,
  width: number,
  height: number,
  mirrorHandle: boolean,
  thickness: number
) {
  const handleX = mirrorHandle ? xOffset + width * 0.15 : xOffset + width * 0.85;
  const handleY = yOffset + height * 0.45;
  const handleRadius = Math.max(15, thickness / 3);
  const backPlateWidth = 30;
  const backPlateHeight = 100;

  dxf.addCircle(
    point3d(handleX, handleY, 0),
    handleRadius,
    { layerName: "HANDLES" }
  );

  dxf.addCircle(
    point3d(handleX, handleY, 0),
    handleRadius / 2,
    { layerName: "HANDLES" }
  );

  dxf.addRectangle(
    point2d(handleX - backPlateWidth / 2, handleY + backPlateHeight / 2),
    point2d(handleX + backPlateWidth / 2, handleY - backPlateHeight / 2),
    { layerName: "HANDLES" }
  );

  dxf.addCircle(
    point3d(handleX, handleY - backPlateHeight / 2 - 30, 0),
    8,
    { layerName: "HANDLES" }
  );
}

function addDimensionAnnotations(
  dxf: DxfWriter,
  width: number,
  height: number,
  thickness: number,
  isDoubleDoor: boolean,
  shape: string,
  topWidth: number
) {
  const dimOffset = 100;

  dxf.addLine(
    point3d(-width/2, -dimOffset, 0),
    point3d(width/2, -dimOffset, 0),
    { layerName: "DIMENSIONS" }
  );
  dxf.addLine(
    point3d(-width/2, -dimOffset - 10, 0),
    point3d(-width/2, -dimOffset + 10, 0),
    { layerName: "DIMENSIONS" }
  );
  dxf.addLine(
    point3d(width/2, -dimOffset - 10, 0),
    point3d(width/2, -dimOffset + 10, 0),
    { layerName: "DIMENSIONS" }
  );
  dxf.addText(
    point3d(0, -dimOffset - 50, 0),
    25,
    `${width}mm`,
    { layerName: "DIMENSIONS" }
  );

  dxf.addLine(
    point3d(-width/2 - dimOffset, 0, 0),
    point3d(-width/2 - dimOffset, height, 0),
    { layerName: "DIMENSIONS" }
  );
  dxf.addLine(
    point3d(-width/2 - dimOffset - 10, 0, 0),
    point3d(-width/2 - dimOffset + 10, 0, 0),
    { layerName: "DIMENSIONS" }
  );
  dxf.addLine(
    point3d(-width/2 - dimOffset - 10, height, 0),
    point3d(-width/2 - dimOffset + 10, height, 0),
    { layerName: "DIMENSIONS" }
  );
  dxf.addText(
    point3d(-width/2 - dimOffset - 50, height/2, 0),
    25,
    `${height}mm`,
    { layerName: "DIMENSIONS", rotation: 90 }
  );

  if (shape === "angled" && topWidth !== width) {
    dxf.addLine(
      point3d(-topWidth/2, height + dimOffset/2, 0),
      point3d(topWidth/2, height + dimOffset/2, 0),
      { layerName: "DIMENSIONS" }
    );
    dxf.addText(
      point3d(0, height + dimOffset/2 + 30, 0),
      20,
      `Top: ${topWidth}mm`,
      { layerName: "DIMENSIONS" }
    );
  }

  dxf.addText(
    point3d(width/2 + dimOffset, height/2, 0),
    20,
    `Thickness: ${thickness}mm`,
    { layerName: "DIMENSIONS" }
  );

  if (isDoubleDoor) {
    dxf.addText(
      point3d(0, height + dimOffset + 80, 0),
      30,
      "DOUBLE DOOR",
      { layerName: "DIMENSIONS" }
    );
  }
}

function addTitleBlock(dxf: DxfWriter, config: DxfDoorConfig) {
  const titleX = config.width / 2 + 200;
  const titleY = 0;
  const lineHeight = 40;
  const specs = [
    `DOOR SPECIFICATION`,
    `==================`,
    `Preset: ${config.preset.toUpperCase()}`,
    `Shape: ${config.shape.toUpperCase()}`,
    `Panel Type: ${config.panelType.toUpperCase()}`,
    `Panel Count: ${config.panelCount}`,
    ``,
    `DIMENSIONS`,
    `Width: ${config.width}mm`,
    `Height: ${config.mainHeight}mm`,
    `Thickness: ${config.thickness}mm`,
    config.shape === "angled" ? `Top Width: ${config.topWidth}mm` : "",
    ``,
    `BORDERS`,
    `Style: ${config.borderStyle.toUpperCase()}`,
    `Top: ${config.borderHeight.top}mm`,
    `Bottom: ${config.borderHeight.bottom}mm`,
    ``,
    `RAILS`,
    `Top Position: ${config.railPosition.top}mm`,
    `Top Height: ${config.railHeights.top}mm`,
    `Middle Position: ${config.railPosition.middle}mm`,
    `Middle Height: ${config.railHeights.middle}mm`,
    ``,
    `MATERIAL & FINISH`,
    `Material: ${config.material.toUpperCase()}`,
    `Finish: ${config.finish.toUpperCase()}`,
    `Color: ${config.color.replace("_", " ").toUpperCase()}`,
  ].filter(line => line !== "");

  specs.forEach((line, index) => {
    dxf.addText(
      point3d(titleX, titleY + (specs.length - index) * lineHeight, 0),
      line.includes("===") || line === "DOOR SPECIFICATION" ? 25 : 18,
      line,
      { layerName: "DIMENSIONS" }
    );
  });
}
